    offers = []
    for i in range(1, m + 1):
        parts = lines[i].split()
        offers.append((int(parts[0]), int(parts[1])))

    results = []

    for x in range(1, n + 1):
        booked = set()
        total = 0

        for l, r in offers:
            duration = r - l + 1
            if duration < x:
                continue

            # Check if this interval overlaps with any booked day
            overlap = False
            for day in range(l, r + 1):
