import math

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    spaceships = []
    for i in range(n):
        x, y = map(int, lines[1 + i].split())
        spaceships.append({'x': x, 'y': y, 'index': i + 1})

    bases = []
    for i in range(n):
        x, y = map(int, lines[1 + n + i].split())
        bases.append({'x': x, 'y': y, 'index': i + 1})

    # Combine all points and compute angular order around a reference
    # Using the leftmost point as reference
    all_points = spaceships + bases

    # Find leftmost point (min x, then min y)
    ref = min(all_points, key=lambda p: (p['x'], p['y']))

    def polar_angle(p):
        return math.atan2(p['y'] - ref['y'], p['x'] - ref['x'])

    # Sort both spaceships and bases by angular order
    spaceships_sorted = sorted(spaceships, key=polar_angle)
    bases_sorted = sorted(bases, key=polar_angle)

    # Create a mapping from original index to sorted position
    result = [0] * n

    # Match corresponding indices after sorting
    for i in range(n):
        result[spaceships[i]['index'] - 1] = bases_sorted[i]['index']

    return '\n'.join(map(str, result))

