        size *= 2

    tree_min = [float('inf')] * (2 * size)
    tree_max = [float('-inf')] * (2 * size)
    tree_lazy = [0] * (2 * size)

    def push_down(node):
        if tree_lazy[node] != 0:
            tree_lazy[2 * node] += tree_lazy[node]
            tree_lazy[2 * node + 1] += tree_lazy[node]
            tree_lazy[node] = 0

    def push_up(node):
        if tree_min[2 * node] < tree_min[2 * node + 1]:
            tree_min[node] = tree_min[2 * node]
        else:
            tree_min[node] = tree_min[2 * node + 1]

        if tree_max[2 * node] > tree_max[2 * node + 1]:
            tree_max[node] = tree_max[2 * node]
        else:
            tree_max[node] = tree_max[2 * node + 1]

    for i in range(n):
        idx = i + size
        tree_min[idx] = A[i]
        tree_max[idx] = A[i]

    for node in range(size - 1, 0, -1):
        push_up(node)

    def range_add(node, start, end, l, r, val):
        if l > r:
            return
        if l <= start and end <= r:
            tree_lazy[node] += val
            return
        push_down(node)
        mid = (start + end) // 2
        range_add(2 * node, start, mid, l, r, val)
        range_add(2 * node + 1, mid + 1, end, l, r, val)
        push_up(node)

    def range_query_max(node, start, end, l, r):
        if l > r:
            return float('-inf')
        if l <= start and end <= r:
            return tree_max[node]
