        if r > mid:
            val = max(val, range_query_max(2 * node + 1, mid + 1, end, l, r))
        return val

    def range_query_min(node, start, end, l, r):
        if l > r:
            return float('inf')
        if l <= start and end <= r:
            return tree_min[node]
        push_down(node)
        mid = (start + end) // 2
        val = float('inf')
        if l <= mid:
            val = min(val, range_query_min(2 * node, start, mid, l, r))
        if r > mid:
            val = min(val, range_query_min(2 * node + 1, mid + 1, end, l, r))
