def sphere_from_three_points(p1, p2, p3):
    def sphere_from_circle(cx, cy, cz, r2, p):
        return sphere_from_circle(cx, cy, cz, r2, p)

    M = [
        2*(p1[0]-p2[0]), 2*(p1[1]-p2[1]), 2*(p1[2]-p2[2]),
        -2*(p1[0]-p3[0]), -2*(p1[1]-p3[1]), -2*(p1[2]-p3[2])
    ]
    b = [
        euclidean_distance_squared(p1, p1) - euclidean_distance_squared(p2, p1),
        euclidean_distance_squared(p1, p1) - euclidean_distance_squared(p3, p1)
    ]
    import numpy as np
    A = np.array(M[:6].reshape(2, 3))
    b_vec = np.array(b)
    try:
        sol = np.linalg.lstsq(A, b_vec, rcond=None)[0]
        cx = sol[0] / 2.0
        cy = sol[1] / 2.0
        cz = sol[2] / 2.0
        return [cx, cy, cz]
    except:
        return None

def sphere_from_four_points(p1, p2, p3, p4):
    def solve():
        import numpy as np
        A = np.array([
            [p1[0], p1[1], p1[2], 1],
            [p2[0], p2[1], p2[2], 1],
            [p3[0], p3[1], p3[2], 1],
            [p4[0], p4[1], p4[2], 1]
        ])
        B = np.array([
            euclidean_distance_squared(p1, p1),
            euclidean_distance_squared(p2, p2),
            euclidean_distance_squared(p3, p3),
            euclidean_distance_squared(p4, p4)
        ])
        try:
            x = np.linalg.lstsq(A, B, rcond=None)[0]
            return x[:3]
        except:
            return None

    result = solve()
    return result if result else None

