        """
        Find the minimum over theta of max(f(theta), g(theta))
        where:
        f(theta) = l*cos(theta) + w*sin(theta)
        g(theta) = l*sin(theta) + w*cos(theta)
        """
        if w >= l:
            return l

        def objective(t):
            return max(
                l * math.cos(t) + w * math.sin(t),
                l * math.sin(t) + w * math.cos(t)
            )

        lo, hi = 0.0, 0.5 * math.pi
        for _ in range(60):
            m1, m2 = lo + (hi - lo) / 3, lo + 2 * (hi - lo) / 3
            if objective(m1) < objective(m2):
                hi = m2
            else:
                lo = m1
        return objective(lo)

