            for j in range(i + 1, len(period)):
                conflict_mask[period[i]] |= (1 << j)
                conflict_mask[period[j]] |= (1 << i)

    max_size = 0

    def dfs(idx, mask, count):
        nonlocal max_size

        # Base case: processed all friends
        if idx == m:
            max_size = max(max_size, count)
            return

        # Pruning: if current count + all remaining can't beat max_size, skip
        if count + (m - idx) <= max_size:
            return

