    sheep = []
    for i in range(n):
        l, r = map(int, lines[i + 1].split())
        sheep.append((l, r, i + 1))

    # Union-Find to connect overlapping sheep
    parent = list(range(n))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py

    # Connect sheep with overlapping ranges
    for i in range(n):
        for j in range(i + 1, n):
            # Ranges [l1, r1] and [l2, r2] overlap if max(l1,l2) <= min(r1,r2)
            if max(sheep[i][0], sheep[j][0]) <= min(sheep[i][1], sheep[j][1]):
                union(i, j)

    # Group into connected components
    components = {}
    for i in range(n):
        root = find(i)
        if root not in components:
            components[root] = []
        components[root].append(i)

    # Determine order for each component (by minimum start time)
    component_key = {}
    for root in components:
        # Find sheep in this component and their min start time
        min_start = min(sheep[find(s)][0] for s in components[root])
        component_key[root] = min_start

    # Sort components by their key
    sorted_components = sorted(components.keys(), key=lambda r: component_key[r])

    # Build result by processing components in order, and within each component sort by start time
    result = []
    for root in sorted_components:
        comp = components[root]
        # Sort sheep in component by start time, then by end time for consistency
        comp.sort(key=lambda i: (sheep[i][0], sheep[i][1]))
        for i in comp:
            result.append(sheep[i][2])

    return ' '.join(map(str, result)) + '\n'

