class LiChaoTree:
    def __init__(self, min_q, max_q):
        self.min_q = min_q
        self.max_q = max_q
        self.n = max(max_q - min_q + 1, 4096)
        if self.n <= 0:
            self.n = 4096
        self.n = 1
        while self.n * 2 < self.n + self.n:  # ensure power of 2
            self.n *= 2
        self.tree = [None] * (self.n * 4)
        # self.histogram = {}  # For lazy removal
        self.size = max_q - min_q + 1

    def _calculate_range_size(self, l, r):
        if l > r:
            return 0
        return r - l + 1

    def _add_line(self, node, l, r, m, c, node_idx=0):
        if self.tree[node_idx] is None:
            self.tree[node_idx] = (m, c)
            return

        mid = (l + r) // 2
        line_old = self.tree[node_idx]
        line_new = (m, c)

        val_old_mid = eval_line(line_old[0], line_old[1], mid)
        val_new_mid = eval_line(line_new[0], line_new[1], mid)

        if val_new_mid > val_old_mid:
            self.tree[node_idx] = line_new
            line_new = line_old
            val_old_mid = val_new_mid

        if l != r:
            if eval_line(line_new[0], line_new[1], l) > eval_line(line_old[0], line_old[1], l):
                self._add_line(2 * node_idx, l, mid, line_new[0], line_new[1], node_idx * 2)
            elif eval_line(line_new[0], line_new[1], r) > eval_line(line_old[0], line_old[1], r):
                self._add_line(2 * node_idx + 1, mid + 1, r, line_new[0], line_new[1], node_idx * 2 + 1)

    def add_line(self, m, c):
        self._add_line(0, self.min_q, self.max_q, m, c, 0)

    def query_max(self, q):
        result = float('-inf')
        node = 0
        l, r = self.min_q, self.max_q

        while node != -1:
            if self.tree[node]:
                result = max(result, eval_line(self.tree[node][0], self.tree[node][1], q))

            mid = (l + r) // 2
            if l == r:
                break

            # Navigate to the child that contains q where parent line is worse
            if eval_line(self.tree[node][0], self.tree[node][1], mid) < eval_line(self.tree[node][0], self.tree[node][1], l if q <= mid else r):
                if q <= mid:
                    node = 2 * node
                    r = mid
                else:
                    node = 2 * node + 1
                    l = mid + 1
            else:
                if q > mid:
                    node = 2 * node + 1
                    l = mid + 1
                else:
                    node = 2 * node
                    r = mid

        return result if result != float('-inf') else None

