    # dp[i] = set of reachable balances after position i
    dp = [set() for _ in range(n)]
    # par[i][bal] = (prev_bal, char) to reconstruct the solution
    par = [[None] * (2 * n + 1) for _ in range(n)]

    # Position 0: start from balance 0
    for c in ['W', 'L', 'D']:
        if s[0] != '?' and s[0] != c:
            continue

        new_bal = 0
        if c == 'W':
            new_bal += 1
        elif c == 'L':
            new_bal -= 1

        # If n > 1, balance after position 0 must not be ±k (before next hand)
        if n > 1 and abs(new_bal) == k:
            continue

        dp[0].add(new_bal)
        par[0][new_bal] = (0, c)

    # Positions 1 to n-1
    for i in range(1, n):
        for prev_bal in list(dp[i - 1]):
            for c in ['W', 'L', 'D']:
                if s[i] != '?' and s[i] != c:
                    continue

                new_bal = prev_bal
                if c == 'W':
                    new_bal += 1
                elif c == 'L':
                    new_bal -= 1

                # If not the last position, balance must not be ±k (before next hand)
                if i < n - 1 and abs(new_bal) == k:
                    continue

                dp[i].add(new_bal)
                par[i][new_bal] = (prev_bal, c)

    # Find final states where |balance| = k
    final_states = []
    for bal in dp[n - 1]:
        if abs(bal) == k:
            final_states.append(bal)

