    rev_map = [0] * (limit + 1)
    for i in range(1, limit + 1):
        rev_map[i] = rev(i)

    # Mark lucky pairs: is_lucky[a][b] = True if a*b == rev(a)*rev(b)
    is_lucky = [[False] * (maxy + 1) for _ in range(maxx + 1)]

    for a in range(1, maxx + 1):
        ra = rev_map[a]
        for b in range(1, maxy + 1):
            rb = rev_map[b]
            if ra * b == a * rb:
                is_lucky[a][b] = True

    # Build 2D prefix sum for O(1) range queries
    # prefix[i][j] = count of lucky tickets in [1,i] x [1,j]
    prefix = [[0] * (maxy + 1) for _ in range(maxx + 1)]

    for i in range(1, maxx + 1):
        for j in range(1, maxy + 1):
            prefix[i][j] = prefix[i-1][j] + prefix[i][j-1] - prefix[i-1][j-1] + (1 if is_lucky[i][j] else 0)

    # Find x, y with minimum x*y that gives at least w lucky tickets
    best_xy = None
    best_cost = float('inf')

    for x in range(1, maxx + 1):
        for y in range(1, maxy + 1):
            count = prefix[x][y]
            if count >= w:
                cost = x * y
                if cost < best_cost:
                    best_cost = cost
                    best_xy = (x, y)

    if best_xy:
        return f"{best_xy[0]} {best_xy[1]}"
    else:
        return "-1"


# Read input and output result
def main():
    import sys
    input_str = sys.stdin.read()
    print(solution(input_str))

# For direct testing
if __name__ == "__main__":
    main()

def solution(X):
    MOD = 10**9 + 7

    def count_digits(n):
        if n == 0:
            return {'0': 1}
        s = str(n)
        counts = {}
        for c in s:
            counts[c] = counts.get(c, 0) + 1
        return counts

    def total_s(n):
        counts = count_digits(n)
        sorted_digits = sorted(counts.keys())
        sorted_digits = [int(d) for d in sorted_digits]
        result = 0
        power = 1
        for d in reversed(sorted_digits):
            result = (result + d * power) % MOD
            if d != sorted_digits[-1]:
                power = (power * 10) % MOD
        return result

    total = 0
    count = 0
    n_str = str(X)

    def dfs(pos, tight, leading_zeros):
        nonlocal total, count
        if pos == len(n_str):
            if leading_zeros == 0:
                count += 1
            return
        limit = int(n_str[pos]) if tight else 9
        for d in range(limit + 1):
            new_leading_zeros = leading_zeros and (d == 0)
            new_tight = tight and (d == limit)
            if not leading_zeros or d != 0:
                dfs(pos + 1, new_tight, new_leading_zeros)

    dfs(0, True, True)
    solution = 0
    for d in range(len(n_str)):
        for digit in range(10):
            count = 0
            solution = (solution + digit * count) % MOD

    return solution
